-- =====================================================================
-- MIVO: NEW database changes only (customer emails; Shopee re-import
-- with BigSeller discount prices; return address falls back to the
-- shop's pickup address; return delivery refund per parcel; MIVO decides return fault; warranty claims for every item).
-- Run just this file in Supabase → SQL Editor. Safe to run again.
-- Generated by supabase/build-run-all.sh from:
--   customer-emails.sql
--   shopee-sync.sql
--   return-address-fallback.sql
--   return-shipping-share.sql
--   return-easyparcel.sql
--   warranty-open-claims.sql
--   liquid-shipping.sql
--   return-parcel-photos.sql
--   returns-window.sql
--   pickup-return-no-markup.sql
--   returns-mivo-review.sql
--   new-user-vouchers.sql
-- =====================================================================

-- ---------------------------------------------------------------------
-- customer-emails.sql
-- ---------------------------------------------------------------------
-- =====================================================================
-- MIVO customer emails. Safe to re-run.
--
-- 1) email_queue: every email MIVO sends (receipt, shipped, delivered,
--    cancelled, refunded, promotions) goes through this table once.
-- 2) Triggers add to the queue when an order is paid / cancelled / refunded
--    and when a parcel ships or is delivered. They never block the order.
-- 3) Promotions: customers choose to receive them (profiles.marketing_opt_in),
--    every promotion has an unsubscribe link.
-- 4) Optional instant sending: after setting Vercel env EMAIL_QUEUE_SECRET, run
--      select public.mivo_email_setup('https://mivo-v2.vercel.app', '<same secret>');
--    Without it, emails still go out from the website itself and the daily check.
-- =====================================================================

begin;

-- --------------------------------------------------------------- 1) queue
create table if not exists public.email_queue (
  id uuid primary key default gen_random_uuid(),
  kind text not null check (kind in ('order_paid', 'order_cancelled', 'order_refunded',
                                     'parcel_shipped', 'parcel_delivered', 'campaign')),
  ref text not null,                       -- what makes it unique, e.g. the order id
  order_id uuid,
  seller_order_id uuid,
  campaign_id uuid,
  user_id uuid,
  recipient text,                          -- filled in when it is sent
  status text not null default 'pending' check (status in ('pending', 'sending', 'sent', 'failed', 'skipped')),
  attempts integer not null default 0,
  last_error text,
  created_at timestamptz not null default now(),
  sent_at timestamptz
);
create unique index if not exists email_queue_kind_ref on public.email_queue (kind, ref);
create index if not exists email_queue_pending on public.email_queue (status, created_at) where status in ('pending', 'sending');
alter table public.email_queue enable row level security;
revoke all on public.email_queue from anon, authenticated;
drop policy if exists "email_queue: admin read" on public.email_queue;
create policy "email_queue: admin read" on public.email_queue for select to authenticated using (public.is_admin());
grant select on public.email_queue to authenticated;

-- Instant sending (pg_net). One row; only the database can read it.
create table if not exists public.mivo_email_settings (
  id boolean primary key default true check (id),
  process_url text not null,
  secret text not null,
  updated_at timestamptz not null default now()
);
alter table public.mivo_email_settings enable row level security;
revoke all on public.mivo_email_settings from anon, authenticated;

create or replace function public.mivo_email_setup(p_site_url text, p_secret text)
returns text language plpgsql security definer set search_path = public as $$
begin
  if coalesce(btrim(p_secret), '') = '' or length(p_secret) < 16 then
    raise exception 'Use a secret of at least 16 characters (the same as EMAIL_QUEUE_SECRET in Vercel)';
  end if;
  begin
    create extension if not exists pg_net;
  exception when others then
    return 'Saved, but pg_net could not be enabled here: turn it on in Database > Extensions';
  end;
  insert into public.mivo_email_settings (id, process_url, secret)
  values (true, rtrim(p_site_url, '/') || '/api/email/process', p_secret)
  on conflict (id) do update set process_url = excluded.process_url, secret = excluded.secret, updated_at = now();
  return 'OK: emails will be sent right away';
end;
$$;
revoke all on function public.mivo_email_setup(text, text) from public, anon, authenticated;

-- Ask the website to send what is waiting. Never raises.
create or replace function public.mivo_email_kick()
returns void language plpgsql security definer set search_path = public as $$
declare s public.mivo_email_settings%rowtype;
begin
  select * into s from public.mivo_email_settings where id;
  if not found or to_regnamespace('net') is null then return; end if;
  execute 'select net.http_post(url := $1, body := ''{}''::jsonb, headers := $2)'
    using s.process_url, jsonb_build_object('Content-Type', 'application/json', 'x-mivo-email-secret', s.secret);
exception when others then
  null;
end;
$$;
revoke all on function public.mivo_email_kick() from public, anon, authenticated;

create or replace function public.mivo_email_enqueue(p_kind text, p_ref text, p_order uuid, p_seller_order uuid, p_user uuid)
returns void language plpgsql security definer set search_path = public as $$
begin
  if p_user is null then return; end if;
  insert into public.email_queue (kind, ref, order_id, seller_order_id, user_id)
  values (p_kind, p_ref, p_order, p_seller_order, p_user)
  on conflict (kind, ref) do nothing;
  if found then perform public.mivo_email_kick(); end if;
exception when others then
  null; -- an email problem must never stop an order from saving
end;
$$;
revoke all on function public.mivo_email_enqueue(text, text, uuid, uuid, uuid) from public, anon, authenticated;

-- Website: take a batch to send (two senders never get the same email).
-- p_campaigns = false while the day's sending limit is used up: order emails still go.
drop function if exists public.mivo_email_claim(integer);
create or replace function public.mivo_email_claim(p_limit integer, p_campaigns boolean default true)
returns setof public.email_queue language sql security definer set search_path = public as $$
  update public.email_queue q
     set status = 'sending', attempts = q.attempts + 1
   where q.id in (
     select id from public.email_queue
      where (status = 'pending' or (status = 'sending' and created_at < now() - interval '15 minutes' and attempts < 5)
             or (status = 'failed' and attempts < 3 and created_at > now() - interval '3 days'))
        and (p_campaigns or kind <> 'campaign')
      order by (kind = 'campaign'), created_at
      limit greatest(1, least(coalesce(p_limit, 20), 100))
      for update skip locked)
  returning q.*;
$$;
revoke all on function public.mivo_email_claim(integer, boolean) from public, anon, authenticated;

-- --------------------------------------------------------------- 2) triggers
create or replace function public.mivo_order_emails()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  n jsonb := to_jsonb(new);
  o jsonb := to_jsonb(old);
  uid uuid := nullif(n ->> 'user_id', '')::uuid;
begin
  if n ->> 'payment_status' = 'paid' and o ->> 'payment_status' is distinct from 'paid' then
    perform public.mivo_email_enqueue('order_paid', new.id::text, new.id, null, uid);
  end if;
  if n ->> 'status' = 'cancelled' and o ->> 'status' is distinct from 'cancelled'
     and coalesce(n ->> 'paid_at', o ->> 'paid_at') is not null then
    perform public.mivo_email_enqueue('order_cancelled', new.id::text, new.id, null, uid);
  end if;
  if n ->> 'payment_status' in ('refunded', 'partially_refunded')
     and o ->> 'payment_status' is distinct from n ->> 'payment_status' then
    perform public.mivo_email_enqueue('order_refunded', new.id::text || ':' || (n ->> 'payment_status'), new.id, null, uid);
  end if;
  return new;
exception when others then
  return new;
end;
$$;
drop trigger if exists orders_customer_emails on public.orders;
create trigger orders_customer_emails after update on public.orders
  for each row execute function public.mivo_order_emails();
revoke all on function public.mivo_order_emails() from public, anon, authenticated;

create or replace function public.mivo_parcel_emails()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  n jsonb := to_jsonb(new);
  o jsonb := to_jsonb(old);
  uid uuid;
begin
  if n ->> 'status' in ('shipped', 'delivered') and o ->> 'status' is distinct from n ->> 'status' then
    select user_id into uid from public.orders where id = new.order_id;
    perform public.mivo_email_enqueue(
      case when n ->> 'status' = 'shipped' then 'parcel_shipped' else 'parcel_delivered' end,
      new.id::text, new.order_id, new.id, coalesce(uid, nullif(n ->> 'customer_id', '')::uuid));
  end if;
  return new;
exception when others then
  return new;
end;
$$;
drop trigger if exists seller_orders_customer_emails on public.seller_orders;
create trigger seller_orders_customer_emails after update on public.seller_orders
  for each row execute function public.mivo_parcel_emails();
revoke all on function public.mivo_parcel_emails() from public, anon, authenticated;

-- --------------------------------------------------------------- 3) promotions
alter table public.profiles add column if not exists marketing_opt_in boolean not null default false;
alter table public.profiles add column if not exists marketing_opt_in_at timestamptz;

-- A customer turns promotions on or off for themselves.
create or replace function public.set_marketing_opt_in(p_on boolean)
returns boolean language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then raise exception 'Please sign in'; end if;
  update public.profiles
     set marketing_opt_in = coalesce(p_on, false),
         marketing_opt_in_at = now()
   where id = auth.uid();
  return coalesce(p_on, false);
end;
$$;
-- {"on": true/false, "decided": has the customer ever chosen}
drop function if exists public.my_marketing_opt_in();
create or replace function public.my_marketing_opt_in()
returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object('on', coalesce(p.marketing_opt_in, false), 'decided', p.marketing_opt_in_at is not null)
    from public.profiles p where p.id = auth.uid();
$$;
revoke all on function public.set_marketing_opt_in(boolean) from public, anon;
revoke all on function public.my_marketing_opt_in() from public, anon;
grant execute on function public.set_marketing_opt_in(boolean) to authenticated;
grant execute on function public.my_marketing_opt_in() to authenticated;

create table if not exists public.email_campaigns (
  id uuid primary key default gen_random_uuid(),
  subject text not null,
  headline text,
  body text not null,
  image_url text,
  button_text text,
  button_url text,
  status text not null default 'sending' check (status in ('sending', 'sent')),
  recipients integer not null default 0,
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now()
);
alter table public.email_campaigns enable row level security;
revoke all on public.email_campaigns from anon, authenticated;
drop policy if exists "email_campaigns: admin read" on public.email_campaigns;
create policy "email_campaigns: admin read" on public.email_campaigns for select to authenticated using (public.is_admin());
grant select on public.email_campaigns to authenticated;

-- Website (after checking the admin): put one email per subscribed customer in the queue.
create or replace function public.mivo_queue_campaign(p_campaign uuid)
returns integer language plpgsql security definer set search_path = public as $$
declare v_count integer;
begin
  insert into public.email_queue (kind, ref, campaign_id, user_id)
  select 'campaign', p_campaign::text || ':' || p.id::text, p_campaign, p.id
    from public.profiles p
   where p.marketing_opt_in and coalesce(btrim(p.email), '') <> ''
  on conflict (kind, ref) do nothing;
  get diagnostics v_count = row_count;
  update public.email_campaigns set recipients = recipients + v_count where id = p_campaign;
  perform public.mivo_email_kick();
  return v_count;
end;
$$;
revoke all on function public.mivo_queue_campaign(uuid) from public, anon, authenticated;

commit;

notify pgrst, 'reload schema';


-- ---------------------------------------------------------------------
-- shopee-sync.sql
-- ---------------------------------------------------------------------
-- =====================================================================
-- MIVO: keep products in step with Shopee. Safe to re-run.
--
-- 1) Each imported product / option remembers its Shopee Item ID and
--    Variation ID (external_ref, e.g. 'shopee:58169897867'), so importing
--    the same listing again updates it instead of adding a copy.
-- 2) mivo_sync_variants: the website updates price / original price / stock
--    of many options in one go (used by Import from Shopee).
-- =====================================================================

begin;

alter table public.products add column if not exists external_ref text;
alter table public.product_variants add column if not exists external_ref text;
create index if not exists products_seller_external_ref on public.products (seller_id, external_ref) where external_ref is not null;
create index if not exists product_variants_seller_external_ref on public.product_variants (seller_id, external_ref) where external_ref is not null;

-- p_rows: [{"id": "<variant uuid>", "price": 128, "compare_at_price": 400, "stock": 10, "external_ref": "shopee:123"}]
-- "stock" and "external_ref" are optional. Only options of p_shop are touched.
create or replace function public.mivo_sync_variants(p_shop uuid, p_rows jsonb)
returns integer language plpgsql security definer set search_path = public as $$
declare v_count integer;
begin
  update public.product_variants v
     set price = greatest(0, r.price),
         compare_at_price = case when r.compare_at_price is not null and r.compare_at_price > r.price then r.compare_at_price end,
         stock_on_hand = coalesce(greatest(0, r.stock), v.stock_on_hand),
         external_ref = coalesce(nullif(r.external_ref, ''), v.external_ref),
         updated_at = now()
    from jsonb_to_recordset(coalesce(p_rows, '[]'::jsonb))
         as r(id uuid, price numeric, compare_at_price numeric, stock integer, external_ref text)
   where v.id = r.id
     and v.seller_id = p_shop
     and r.price is not null;
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;
revoke all on function public.mivo_sync_variants(uuid, jsonb) from public, anon, authenticated;

commit;

notify pgrst, 'reload schema';


-- ---------------------------------------------------------------------
-- return-address-fallback.sql
-- ---------------------------------------------------------------------
-- =====================================================================
-- Returns: where the customer sends the item back. Safe to re-run.
-- Uses the shop's return address; when that is empty, the shop's pickup
-- address (usually the same warehouse), so the customer always sees one.
-- =====================================================================

begin;

create or replace function public.return_request_return_address(p_request_id uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v jsonb;
  s record;
  pickup jsonb;
  line text;
begin
  select sl.shop_name, sl.return_name, sl.return_phone, sl.return_address,
         to_jsonb(sl) -> 'pickup_address' as pickup_address, to_jsonb(sl) ->> 'phone' as shop_phone
    into s
    from public.return_requests r join public.sellers sl on sl.id = r.seller_id
   where r.id = p_request_id and r.customer_id = auth.uid()
     and r.status in ('approved_return', 'returning');
  if not found then return null; end if;

  if coalesce(btrim(s.return_address), '') <> '' then
    return jsonb_build_object('shop', s.shop_name, 'name', s.return_name, 'phone', s.return_phone, 'address', s.return_address);
  end if;

  pickup := case when jsonb_typeof(s.pickup_address) = 'object' then s.pickup_address else '{}'::jsonb end;
  line := concat_ws(', ',
    nullif(btrim(coalesce(pickup ->> 'line', pickup ->> 'address_line_1', pickup ->> 'address', '')), ''),
    nullif(btrim(coalesce(pickup ->> 'line2', pickup ->> 'address_line_2', '')), ''),
    nullif(btrim(concat_ws(' ', pickup ->> 'postcode', pickup ->> 'city')), ''),
    nullif(btrim(coalesce(pickup ->> 'state', '')), ''));
  if coalesce(line, '') = '' then
    return jsonb_build_object('shop', s.shop_name, 'name', s.return_name, 'phone', s.return_phone, 'address', null);
  end if;
  v := jsonb_build_object(
    'shop', s.shop_name,
    'name', coalesce(nullif(btrim(s.return_name), ''), pickup ->> 'name', s.shop_name),
    'phone', coalesce(nullif(btrim(s.return_phone), ''), pickup ->> 'phone', s.shop_phone),
    'address', line);
  return v;
end;
$$;
revoke all on function public.return_request_return_address(uuid) from public, anon;
grant execute on function public.return_request_return_address(uuid) to authenticated;

commit;

notify pgrst, 'reload schema';


-- ---------------------------------------------------------------------
-- return-shipping-share.sql
-- ---------------------------------------------------------------------
-- =====================================================================
-- Returns: the delivery fee refunded for a faulty item now comes from the
-- parcel it was shipped in (each shop charges its own delivery; shops that
-- ship together share one fee), scaled to what the buyer actually paid.
-- Before, it was a share of the whole order's delivery, so returning an
-- item from a free-shipping shop could refund another shop's delivery fee.
-- Older orders without per-shop fees keep the previous rule. Safe to re-run.
-- =====================================================================

begin;

create or replace function public.mivo_return_quote(p_order_id uuid, p_items jsonb, p_reason text)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  o public.orders%rowtype;
  v_items numeric := 0;
  v_goods numeric;
  v_share numeric;
  v_fault boolean;
  v_verified boolean;
  v_shipping numeric := 0;
  v_all_fees numeric := 0;
  v_fee numeric := 0;
  v_already numeric := 0;
  v_refund numeric;
begin
  select * into o from public.orders where id = p_order_id;
  if not found then raise exception 'Order not found'; end if;

  select coalesce(sum(oi.unit_price * least((x.value->>'quantity')::int, oi.quantity)), 0),
         bool_and(coalesce(s.tier, 'standard') = 'direct')
    into v_items, v_verified
  from jsonb_array_elements(p_items) x
  join public.order_items oi on oi.id = (x.value->>'order_item_id')::uuid and oi.order_id = o.id
  left join public.sellers s on s.id = oi.seller_id;

  -- Item price after the order's voucher discount.
  v_items := round(v_items * greatest(o.subtotal - coalesce(o.discount_amount, 0), 0) / nullif(o.subtotal, 0), 2);
  v_items := coalesce(v_items, 0);
  v_goods := greatest(o.total_amount - coalesce(o.shipping_amount, 0), 0);
  v_share := case when v_goods > 0 then least(v_items / v_goods, 1) else 0 end;

  v_fault := p_reason in ('wrong_item','damaged','defective','not_as_described','missing_parts','not_received')
          or (p_reason = 'does_not_fit' and coalesce(v_verified, false));

  if v_fault then
    -- Delivery fee of the parcel(s) the items came in (each shop ships and
    -- charges separately; shops shipping together share one fee), scaled to
    -- what the buyer actually paid for delivery (after free-shipping promos),
    -- in proportion to the part of that parcel being returned.
    select coalesce(sum(coalesce(so.buyer_shipping_fee, 0)), 0) into v_all_fees
      from public.seller_orders so where so.order_id = o.id;
    if v_all_fees > 0 then
      with returned as (
        select coalesce(so.shipping_group, so.id::text) as grp,
               sum(oi.unit_price * least((x.value->>'quantity')::int, oi.quantity)) as value
          from jsonb_array_elements(p_items) x
          join public.order_items oi on oi.id = (x.value->>'order_item_id')::uuid and oi.order_id = o.id
          join public.seller_orders so on so.id = oi.seller_order_id
         group by 1
      ), groups as (
        select coalesce(so.shipping_group, so.id::text) as grp,
               sum(coalesce(so.buyer_shipping_fee, 0)) as fee,
               sum(coalesce(so.subtotal, 0)) as goods
          from public.seller_orders so where so.order_id = o.id
         group by 1
      )
      select coalesce(sum(coalesce(o.shipping_amount, 0) * g.fee / v_all_fees
                          * least(r.value / nullif(g.goods, 0), 1)), 0)
        into v_shipping
        from returned r join groups g using (grp);
      v_shipping := round(coalesce(v_shipping, 0), 2);
    else
      v_shipping := round(coalesce(o.shipping_amount, 0) * v_share, 2);
    end if;
  else
    v_fee := round(coalesce(o.payment_processing_fee_amount, 0) * v_share, 2);
  end if;

  -- Never refund more than what is left of the order.
  select coalesce(sum(coalesce(final_amount, requested_amount)), 0) into v_already
  from public.return_requests
  where order_id = o.id and status in ('refunding','refunded');
  v_refund := least(greatest(v_items + v_shipping - v_fee, 0),
                    greatest(o.total_amount - coalesce(o.cancellation_refund_amount, 0) - v_already, 0));

  return jsonb_build_object(
    'seller_fault', v_fault, 'items_amount', v_items, 'shipping_refund', v_shipping,
    'fee_deduction', v_fee, 'refund_amount', v_refund, 'max_refund',
    greatest(o.total_amount - coalesce(o.cancellation_refund_amount, 0) - v_already, 0));
end;
$$;

revoke all on function public.mivo_return_quote(uuid, jsonb, text) from public, anon, authenticated;

commit;


-- ---------------------------------------------------------------------
-- return-easyparcel.sql
-- ---------------------------------------------------------------------
-- =====================================================================
-- Returns: MIVO decides whose fault it is, and books the return parcel.
--   * The customer's reason is only their claim. When accepting, MIVO
--     (admin) chooses "our fault" (item + its delivery share refunded,
--     return parcel booked and paid by MIVO via EasyParcel) or "not our
--     fault" (change-of-mind rules: no delivery refund, payment fee
--     deducted, customer sends it back at their own cost).
--   * A return booked with EasyParcel stores its AWB / label on the
--     request; the customer drops it off at a courier point and taps
--     "I've dropped it off".
-- Safe to re-run.
-- =====================================================================

begin;

alter table public.return_requests add column if not exists fault_decided_by text;
alter table public.return_requests add column if not exists return_awb_url text;
alter table public.return_requests add column if not exists return_ep_shipment text;
alter table public.return_requests add column if not exists return_label_cost numeric(12,2);
alter table public.return_requests add column if not exists return_booked_at timestamptz;

-- MIVO accepts a request and decides fault. Amounts are recalculated with
-- the same quote rules (faulty vs change of mind).
create or replace function public.return_request_mivo_accept(p_id uuid, p_our_fault boolean, p_note text default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare r public.return_requests%rowtype; v_quote jsonb; v_amount numeric;
begin
  if not public.is_admin() then raise exception 'Only MIVO can decide this'; end if;
  select * into r from public.return_requests where id = p_id for update;
  if not found then raise exception 'Request not found'; end if;
  if r.status not in ('requested', 'mivo_review', 'seller_offer') then raise exception 'This request is already %', r.status; end if;

  v_quote := public.mivo_return_quote(r.order_id, r.items, case when p_our_fault then 'defective' else 'changed_mind' end);
  v_amount := (v_quote->>'refund_amount')::numeric;

  update public.return_requests
     set seller_fault = p_our_fault,
         fault_decided_by = 'mivo',
         items_amount = (v_quote->>'items_amount')::numeric,
         shipping_refund = (v_quote->>'shipping_refund')::numeric,
         fee_deduction = (v_quote->>'fee_deduction')::numeric,
         requested_amount = v_amount,
         status = case when needs_return then 'approved_return' else 'refunding' end,
         final_amount = case when needs_return then null else v_amount end,
         ship_back_by = case when needs_return then now() + interval '7 days' end,
         mivo_note = coalesce(nullif(btrim(coalesce(p_note, '')), ''), mivo_note),
         updated_at = now()
   where id = r.id;
  perform public.mivo_return_log(r.id, 'mivo', case when p_our_fault then 'accepted_our_fault' else 'accepted_not_our_fault' end, p_note, v_amount);
  return jsonb_build_object('refund_amount', v_amount, 'needs_return', r.needs_return, 'our_fault', p_our_fault);
end;
$$;
revoke all on function public.return_request_mivo_accept(uuid, boolean, text) from public, anon;
grant execute on function public.return_request_mivo_accept(uuid, boolean, text) to authenticated;

-- Customer: dropped the pre-booked return parcel off at the courier.
create or replace function public.return_request_customer_dropped(p_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare r public.return_requests%rowtype;
begin
  select * into r from public.return_requests where id = p_id for update;
  if not found or r.customer_id <> auth.uid() then raise exception 'Request not found'; end if;
  if r.status <> 'approved_return' or r.return_tracking is null then raise exception 'This action is not available now'; end if;
  update public.return_requests set status = 'returning', shipped_back_at = now(), updated_at = now() where id = r.id;
  perform public.mivo_return_log(r.id, 'customer', 'shipped_back', coalesce(r.return_courier, '') || ' ' || r.return_tracking, null);
end;
$$;
revoke all on function public.return_request_customer_dropped(uuid) from public, anon;
grant execute on function public.return_request_customer_dropped(uuid) to authenticated;

commit;
notify pgrst, 'reload schema';

-- A return request needs at least one photo or video (except "not received").
begin;
create or replace function public.mivo_return_needs_photo()
returns trigger language plpgsql as $$
begin
  if new.reason <> 'not_received' and cardinality(coalesce(new.evidence_paths, '{}')) = 0 then
    raise exception 'Add at least one photo or video of the item';
  end if;
  return new;
end;
$$;
drop trigger if exists return_requests_need_photo on public.return_requests;
create trigger return_requests_need_photo before insert on public.return_requests
  for each row execute function public.mivo_return_needs_photo();
commit;


-- ---------------------------------------------------------------------
-- warranty-open-claims.sql
-- ---------------------------------------------------------------------
-- =====================================================================
-- Warranty claims for every delivered item. Items whose shop hasn't set a
-- warranty period can still be claimed; MIVO approves or rejects each claim.
-- A rejected claim must carry a reason for the customer. Safe to re-run.
-- =====================================================================

begin;

create or replace function public.create_warranty_claim(
  p_order_number text,
  p_order_item_id uuid,
  p_issue_type text,
  p_description text,
  p_image_urls text[] default '{}'
)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  o public.orders%rowtype;
  oi public.order_items%rowtype;
  v_start timestamptz;
  v_expires timestamptz;
  v_number text;
  c public.warranty_claims%rowtype;
begin
  if auth.uid() is null then raise exception 'Please sign in'; end if;
  select * into o from public.orders where order_number = p_order_number and user_id = auth.uid();
  if not found then raise exception 'Order not found'; end if;
  if o.status not in ('delivered', 'completed') then
    raise exception 'Warranty claims open once the order is delivered';
  end if;
  select * into oi from public.order_items where id = p_order_item_id and order_id = o.id;
  if not found then raise exception 'Item not found in this order'; end if;
  if p_issue_type not in ('defect','noise','leakage','fitment','damage','performance','other') then
    raise exception 'Choose an issue type';
  end if;
  if length(btrim(coalesce(p_description, ''))) < 10 then
    raise exception 'Describe the problem (at least 10 characters)';
  end if;
  if cardinality(coalesce(p_image_urls, '{}')) > 6 then raise exception 'Up to 6 photos per claim'; end if;

  v_start := coalesce(
    (select max(h.created_at) from public.order_status_history h where h.order_id = o.id and h.new_status = 'delivered'),
    o.paid_at, o.created_at);
  -- No set warranty: no fixed end date, MIVO decides.
  v_expires := v_start + make_interval(months => greatest(coalesce(oi.warranty_months, 0), 0));
  if coalesce(oi.warranty_months, 0) > 0 and now() > v_expires then
    raise exception 'The warranty for this item has expired';
  end if;

  if exists (select 1 from public.warranty_claims w where w.order_item_id = oi.id and w.user_id = auth.uid()
               and w.status in ('new', 'reviewing', 'approved')) then
    raise exception 'There is already an active warranty claim for this item';
  end if;

  v_number := 'WC' || to_char(now() at time zone 'Asia/Kuala_Lumpur', 'YYMMDD') || '-'
              || upper(substr(md5(gen_random_uuid()::text), 1, 6));

  insert into public.warranty_claims (
    claim_number, user_id, order_id, order_number, order_item_id, product_id, product_name, variant_name,
    warranty_months, warranty_start_at, warranty_expires_at, issue_type, description, image_urls)
  values (
    v_number, auth.uid(), o.id, o.order_number, oi.id, oi.product_id, oi.product_name, oi.variant_name,
    coalesce(oi.warranty_months, 0), v_start, v_expires, p_issue_type, btrim(p_description), coalesce(p_image_urls, '{}'))
  returning * into c;

  return jsonb_build_object('id', c.id, 'claim_number', c.claim_number, 'status', c.status, 'created_at', c.created_at);
end;
$$;
revoke all on function public.create_warranty_claim(text, uuid, text, text, text[]) from public, anon;
grant execute on function public.create_warranty_claim(text, uuid, text, text, text[]) to authenticated;

create or replace function public.admin_update_warranty_claim(
  p_claim_id uuid, p_status text, p_admin_note text default null, p_resolution_note text default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare c public.warranty_claims%rowtype;
begin
  if not public.is_admin() then raise exception 'Only MIVO admins can update warranty claims'; end if;
  if p_status not in ('new','reviewing','approved','rejected','completed') then
    raise exception 'Unknown claim status %', p_status;
  end if;
  if p_status = 'rejected' and length(btrim(coalesce(p_admin_note, ''))) < 5 then
    raise exception 'Write the reason for the customer in "Customer update" before rejecting';
  end if;
  update public.warranty_claims
     set status = p_status,
         admin_note = nullif(btrim(coalesce(p_admin_note, '')), ''),
         resolution_note = nullif(btrim(coalesce(p_resolution_note, '')), ''),
         reviewed_by = auth.uid(), reviewed_at = now(), updated_at = now()
   where id = p_claim_id
  returning * into c;
  if not found then raise exception 'Claim not found'; end if;
  return jsonb_build_object('id', c.id, 'claim_number', c.claim_number, 'status', c.status);
end;
$$;
revoke all on function public.admin_update_warranty_claim(uuid, text, text, text) from public, anon;
grant execute on function public.admin_update_warranty_claim(uuid, text, text, text) to authenticated;

commit;
notify pgrst, 'reload schema';


-- ---------------------------------------------------------------------
-- liquid-shipping.sql
-- ---------------------------------------------------------------------
-- =====================================================================
-- Liquids (engine oil, coolant, ATF / CVT / gear oil) can't be shipped to
-- Sabah, Sarawak or Labuan. Marks every matching product now, and new
-- products (e.g. Shopee imports) as they're added. Oil filters, coolers,
-- hoses, tanks and other parts are not matched. Safe to re-run.
-- To undo for one product: untick the states on its edit page.
-- =====================================================================

begin;

create or replace function public.mivo_is_liquid_product(p_name text)
returns boolean language sql immutable as $$
  select coalesce(p_name, '') ~* '(engine|motor|gear|gearbox|diesel|transmission)\s*oil|minyak\s*(hitam|enjin|engine|gear|gearbox|auto)|coolant|anti-?freeze|\matf\M|transmission\s*fluid|\mcvt\s*fluid|\m(0|5|10|15|20|75|80|85)w[- ]?\d{2}\M'
     and (coalesce(p_name, '') ~* '\d+(\.\d+)?\s*(l|lit(re|er)s?|ltrs?|ml)\M'
          or coalesce(p_name, '') ~* 'synthetic|mineral|fluid|minyak\s*(hitam|enjin|gear|gearbox|auto)|anti-?freeze|\matf\M|\m(0|5|10|15|20|75|80|85)w[- ]?\d{2}\M'
          or coalesce(p_name, '') !~* 'filter|seal|pump|sensor|hose|pipe|cooler|\mcap\M|tank|reservoir|\mpan\M|gasket|switch|dipstick|bottle|bracket|thermostat|valve|housing|radiator\s*(assy|core)|fan');
$$;

create temp table liquid_before on commit drop as
  select id from public.products
   where public.mivo_is_liquid_product(name)
     and restricted_shipping_states @> array['Sabah','Sarawak','W.P. Labuan'];

update public.products
   set restricted_shipping_states = (
         select array_agg(distinct s order by s)
           from unnest(coalesce(restricted_shipping_states, '{}') || array['Sabah','Sarawak','W.P. Labuan']) s),
       updated_at = now()
 where public.mivo_is_liquid_product(name)
   and not (coalesce(restricted_shipping_states, '{}') @> array['Sabah','Sarawak','W.P. Labuan']);

-- New products: same rule when they're added.
create or replace function public.mivo_products_liquid_rule()
returns trigger language plpgsql as $$
begin
  if public.mivo_is_liquid_product(new.name)
     and not (coalesce(new.restricted_shipping_states, '{}') @> array['Sabah','Sarawak','W.P. Labuan']) then
    new.restricted_shipping_states := (
      select array_agg(distinct s order by s)
        from unnest(coalesce(new.restricted_shipping_states, '{}') || array['Sabah','Sarawak','W.P. Labuan']) s);
  end if;
  return new;
end;
$$;
drop trigger if exists products_liquid_rule on public.products;
create trigger products_liquid_rule before insert on public.products
  for each row execute function public.mivo_products_liquid_rule();

create temp table liquid_summary on commit preserve rows as
  select s.shop_name as shop, count(*) as liquid_products,
         count(*) filter (where p.id not in (select id from liquid_before)) as newly_restricted
    from public.products p join public.sellers s on s.id = p.seller_id
   where public.mivo_is_liquid_product(p.name)
   group by s.shop_name order by s.shop_name;

commit;
select * from liquid_summary;


-- ---------------------------------------------------------------------
-- return-parcel-photos.sql
-- ---------------------------------------------------------------------
-- =====================================================================
-- Returns: the customer adds photos of the packed parcel / drop-off
-- receipt when sending the item back. "I've dropped it off" needs at
-- least one. Safe to re-run.
-- =====================================================================

begin;

alter table public.return_requests add column if not exists return_parcel_photos text[] not null default '{}';

create or replace function public.return_request_add_parcel_photos(p_id uuid, p_paths text[])
returns void language plpgsql security definer set search_path = public as $$
declare r public.return_requests%rowtype;
begin
  select * into r from public.return_requests where id = p_id for update;
  if not found or r.customer_id <> auth.uid() then raise exception 'Request not found'; end if;
  if r.status not in ('approved_return', 'returning') then raise exception 'Photos can be added while sending the item back'; end if;
  if exists (select 1 from unnest(coalesce(p_paths, '{}')) p where split_part(p, '/', 1) <> auth.uid()::text) then
    raise exception 'Invalid photo';
  end if;
  update public.return_requests
     set return_parcel_photos = (array(select distinct x from unnest(coalesce(return_parcel_photos, '{}') || coalesce(p_paths, '{}')) x))[1:6],
         updated_at = now()
   where id = r.id;
end;
$$;
revoke all on function public.return_request_add_parcel_photos(uuid, text[]) from public, anon;
grant execute on function public.return_request_add_parcel_photos(uuid, text[]) to authenticated;

-- Dropping off a booked return needs a parcel photo.
create or replace function public.return_request_customer_dropped(p_id uuid)
returns void language plpgsql security definer set search_path = public as $$
declare r public.return_requests%rowtype;
begin
  select * into r from public.return_requests where id = p_id for update;
  if not found or r.customer_id <> auth.uid() then raise exception 'Request not found'; end if;
  if r.status <> 'approved_return' or r.return_tracking is null then raise exception 'This action is not available now'; end if;
  if cardinality(coalesce(r.return_parcel_photos, '{}')) = 0 then raise exception 'Add a photo of the parcel first'; end if;
  update public.return_requests set status = 'returning', shipped_back_at = now(), updated_at = now() where id = r.id;
  perform public.mivo_return_log(r.id, 'customer', 'shipped_back', coalesce(r.return_courier, '') || ' ' || r.return_tracking, null);
end;
$$;
revoke all on function public.return_request_customer_dropped(uuid) from public, anon;
grant execute on function public.return_request_customer_dropped(uuid) to authenticated;

commit;
notify pgrst, 'reload schema';


-- ---------------------------------------------------------------------
-- returns-window.sql
-- ---------------------------------------------------------------------
-- =====================================================================
-- Return window and automatic completion
--   * 7 days after delivery (EasyParcel tracking or "Mark delivered") the
--     order is completed automatically, unless a return is open.
--   * Returns can be requested up to 15 days after delivery. Within 7 days
--     a return MIVO accepts as its fault gets a free EasyParcel return;
--     from day 8 the customer posts it back to MIVO HUB at their own cost.
-- Safe to re-run.
-- =====================================================================

begin;

alter table public.return_requests add column if not exists free_return boolean not null default true;

create or replace function public.return_request_create(
  p_order_number text, p_items jsonb, p_reason text, p_solution text,
  p_description text, p_evidence text[]
)
returns uuid language plpgsql security definer set search_path = public as $$
declare
  o public.orders%rowtype;
  v_quote jsonb;
  v_seller_orders int;
  v_seller_order uuid;
  v_seller uuid;
  v_delivered timestamptz;
  v_id uuid;
  v_number text;
  v_free boolean;
begin
  select * into o from public.orders where order_number = p_order_number and user_id = auth.uid() for update;
  if not found then raise exception 'Order not found'; end if;
  if o.status not in ('shipped','delivered','completed') then
    raise exception 'Returns open once the order has shipped';
  end if;
  if o.status = 'shipped' and p_reason <> 'not_received' and p_reason <> 'damaged' then
    raise exception 'Please confirm you received the order first, or choose "not received"';
  end if;
  v_delivered := public.mivo_order_delivered_at(o.id);
  if o.status in ('delivered','completed') and coalesce(v_delivered, o.updated_at) < now() - interval '15 days' then
    raise exception 'The 15-day return window for this order has passed. Please use a warranty claim instead.';
  end if;
  -- Within 7 days of delivery a return MIVO accepts as its fault is booked for free;
  -- after that (days 8-15) the customer posts it back at their own cost.
  v_free := o.status = 'shipped' or coalesce(v_delivered, o.updated_at) >= now() - interval '7 days';
  if p_solution not in ('return_refund','refund_only') then raise exception 'Choose return & refund or refund only'; end if;
  if p_solution = 'refund_only' and p_reason not in ('not_received','missing_parts') then
    raise exception 'Refund without returning the item is only for items not received or missing parts';
  end if;
  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'Choose at least one item';
  end if;
  if (select count(*) from jsonb_array_elements(p_items) x
       left join public.order_items oi on oi.id = (x.value->>'order_item_id')::uuid and oi.order_id = o.id
      where oi.id is null or coalesce((x.value->>'quantity')::int, 0) < 1
         or (x.value->>'quantity')::int > oi.quantity) > 0 then
    raise exception 'Invalid items or quantities';
  end if;

  select count(distinct oi.seller_order_id), min(oi.seller_order_id::text)::uuid, min(oi.seller_id::text)::uuid
    into v_seller_orders, v_seller_order, v_seller
  from jsonb_array_elements(p_items) x
  join public.order_items oi on oi.id = (x.value->>'order_item_id')::uuid;
  if v_seller_orders > 1 then raise exception 'Request items from one shop at a time'; end if;

  if exists (
    select 1 from public.return_requests r, jsonb_array_elements(r.items) ri, jsonb_array_elements(p_items) x
     where r.order_id = o.id and r.status not in ('rejected','cancelled','closed')
       and ri.value->>'order_item_id' = x.value->>'order_item_id'
  ) then
    raise exception 'There is already a return request for one of these items';
  end if;

  v_quote := public.mivo_return_quote(o.id, p_items, p_reason);
  if (v_quote->>'refund_amount')::numeric <= 0 then raise exception 'Nothing left to refund on this order'; end if;

  v_number := 'RR' || to_char(now(), 'YYMMDD') || '-' || upper(substr(md5(gen_random_uuid()::text), 1, 5));

  insert into public.return_requests (
    request_number, order_id, seller_order_id, seller_id, customer_id, items, reason, solution,
    description, evidence_paths, seller_fault, items_amount, shipping_refund, fee_deduction,
    requested_amount, needs_return, respond_by, free_return)
  values (
    v_number, o.id, v_seller_order, v_seller, auth.uid(), p_items, p_reason, p_solution,
    nullif(btrim(coalesce(p_description, '')), ''), coalesce(p_evidence, '{}'),
    (v_quote->>'seller_fault')::boolean, (v_quote->>'items_amount')::numeric,
    (v_quote->>'shipping_refund')::numeric, (v_quote->>'fee_deduction')::numeric,
    (v_quote->>'refund_amount')::numeric, p_solution = 'return_refund', now() + interval '2 days', v_free)
  returning id into v_id;

  perform public.mivo_return_log(v_id, 'customer', 'requested', p_description, (v_quote->>'refund_amount')::numeric);
  return v_id;
end;
$$;

create or replace function public.mivo_auto_complete_orders()
returns integer language plpgsql security definer set search_path = public as $$
declare r record; v_count integer := 0;
begin
  for r in
    select o.id from public.orders o
     where o.status = 'delivered'
       and coalesce(public.mivo_order_delivered_at(o.id), o.delivered_at, o.updated_at) < now() - interval '7 days'
       and not exists (select 1 from public.return_requests q where q.order_id = o.id
                        and q.status not in ('rejected','cancelled','closed','refunded'))
     for update skip locked
  loop
    update public.orders set status = 'completed', updated_at = now() where id = r.id;
    update public.seller_orders set status = 'completed' where order_id = r.id and status = 'delivered';
    insert into public.order_status_history (order_id, old_status, new_status, note)
    values (r.id, 'delivered', 'completed', 'Completed automatically 7 days after delivery');
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$$;
revoke all on function public.mivo_auto_complete_orders() from public, anon, authenticated;

commit;
notify pgrst, 'reload schema';


-- ---------------------------------------------------------------------
-- pickup-return-no-markup.sql
-- ---------------------------------------------------------------------
-- =====================================================================
-- 1. Returns go back to the shop's pickup (sender) address, with the
--    pickup contact name and phone, for every approved return (our fault
--    or change of mind). The old "return address" is only used when a
--    shop has no pickup address.
-- 2. No MIVO markup on shipping: the fallback rate card adds RM 0.
--    (With EasyParcel connected, checkout charges EasyParcel's price.)
-- Safe to re-run.
-- =====================================================================

begin;

create or replace function public.return_request_return_address(p_request_id uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  s record;
  pickup jsonb;
  line text;
begin
  select sl.shop_name, sl.return_name, sl.return_phone, sl.return_address,
         to_jsonb(sl) -> 'pickup_address' as pickup_address, to_jsonb(sl) ->> 'phone' as shop_phone
    into s
    from public.return_requests r join public.sellers sl on sl.id = r.seller_id
   where r.id = p_request_id and r.customer_id = auth.uid()
     and r.status in ('approved_return', 'returning');
  if not found then return null; end if;

  pickup := case when jsonb_typeof(s.pickup_address) = 'object' then s.pickup_address else '{}'::jsonb end;
  line := concat_ws(', ',
    nullif(btrim(coalesce(pickup ->> 'line', pickup ->> 'address_line_1', pickup ->> 'address', '')), ''),
    nullif(btrim(coalesce(pickup ->> 'line2', pickup ->> 'address_line_2', '')), ''),
    nullif(btrim(concat_ws(' ', pickup ->> 'postcode', pickup ->> 'city')), ''),
    nullif(btrim(coalesce(pickup ->> 'state', '')), ''));

  if coalesce(line, '') <> '' then
    return jsonb_build_object(
      'shop', s.shop_name,
      'name', coalesce(nullif(btrim(pickup ->> 'name'), ''), nullif(btrim(s.return_name), ''), s.shop_name),
      'phone', coalesce(nullif(btrim(pickup ->> 'phone'), ''), nullif(btrim(s.return_phone), ''), s.shop_phone),
      'address', line);
  end if;

  return jsonb_build_object('shop', s.shop_name, 'name', s.return_name,
    'phone', coalesce(nullif(btrim(s.return_phone), ''), s.shop_phone),
    'address', nullif(btrim(coalesce(s.return_address, '')), ''));
end;
$$;
revoke all on function public.return_request_return_address(uuid) from public, anon;
grant execute on function public.return_request_return_address(uuid) to authenticated;

update public.shipping_rules set handling_markup = 0 where handling_markup <> 0;

commit;

notify pgrst, 'reload schema';


-- ---------------------------------------------------------------------
-- returns-mivo-review.sql
-- ---------------------------------------------------------------------
-- =====================================================================
-- Every return / refund request is decided by MIVO.
--   * A shop can only give its view (agree, suggest a partial refund, or
--     disagree). The request keeps waiting for MIVO's decision.
--   * No more automatic approval when a shop doesn't answer within 2 days.
--   * A parcel sent back counts as arrived only when MIVO (or the shop)
--     marks it received. If nobody does within 14 days, it goes to MIVO's
--     review list instead of being refunded automatically.
--   * After it is marked received, the 3-day inspection and automatic
--     refund work as before, for the amount MIVO approved.
-- Safe to re-run.
-- =====================================================================

begin;

create or replace function public.return_request_seller_respond(p_id uuid, p_action text, p_amount numeric, p_note text)
returns void language plpgsql security definer set search_path = public as $$
declare r public.return_requests%rowtype;
begin
  select * into r from public.return_requests where id = p_id for update;
  if not found then raise exception 'Request not found'; end if;
  if not public.mivo_can_manage_shop(r.seller_id) then raise exception 'Not allowed'; end if;
  if r.status <> 'requested' then raise exception 'This request is already %', r.status; end if;

  if p_action = 'accept' then
    -- The shop agrees; MIVO still decides.
    update public.return_requests
       set seller_note = coalesce(nullif(btrim(coalesce(p_note, '')), ''), 'Shop agrees with this request.'),
           seller_amount = null, updated_at = now()
     where id = r.id;
    perform public.mivo_return_log(r.id, 'seller', 'seller_agreed', p_note, r.requested_amount);
  elsif p_action = 'offer' then
    -- A suggestion for MIVO (customer keeps the item); the customer isn't asked.
    if p_amount is null or p_amount <= 0 or p_amount >= r.requested_amount then
      raise exception 'Suggest an amount between RM0 and RM%', r.requested_amount;
    end if;
    update public.return_requests
       set seller_amount = round(p_amount, 2),
           seller_note = nullif(btrim(coalesce(p_note, '')), ''), updated_at = now()
     where id = r.id;
    perform public.mivo_return_log(r.id, 'seller', 'seller_suggested', p_note, round(p_amount, 2));
  elsif p_action = 'dispute' then
    if coalesce(btrim(p_note), '') = '' then raise exception 'Explain why you disagree'; end if;
    update public.return_requests
       set status = 'mivo_review', dispute_note = btrim(p_note), updated_at = now()
     where id = r.id;
    perform public.mivo_return_log(r.id, 'seller', 'disputed', p_note, null);
  else
    raise exception 'Unknown action';
  end if;
end;
$$;

create or replace function public.return_requests_auto()
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_closed int := 0; v_overdue int := 0; v_refund int := 0; r record;
begin
  -- Approved, but the item wasn't sent back in time.
  for r in select id from public.return_requests
            where status = 'approved_return' and ship_back_by < now() and return_tracking is null loop
    update public.return_requests set status = 'closed', updated_at = now() where id = r.id;
    perform public.mivo_return_log(r.id, 'system', 'auto_closed', 'Item was not sent back within 7 days', null);
    v_closed := v_closed + 1;
  end loop;

  -- Sent back 14+ days ago and nobody marked it received: MIVO checks it.
  for r in select id from public.return_requests
            where status = 'returning' and coalesce(shipped_back_at, updated_at) < now() - interval '14 days' loop
    update public.return_requests
       set status = 'mivo_review',
           dispute_note = coalesce(dispute_note, 'Parcel not marked received 14 days after it was sent back'),
           updated_at = now()
     where id = r.id;
    perform public.mivo_return_log(r.id, 'system', 'review_overdue', 'Parcel not marked received 14 days after it was sent back', null);
    v_overdue := v_overdue + 1;
  end loop;

  -- Marked received and no problem reported within 3 days: refund the approved amount.
  for r in select id, coalesce(final_amount, requested_amount) as amount from public.return_requests
            where status = 'received' and inspect_by < now() loop
    update public.return_requests
       set status = 'refunding', final_amount = r.amount, updated_at = now()
     where id = r.id;
    perform public.mivo_return_log(r.id, 'system', 'auto_refund', 'No problem reported within 3 days of arrival', r.amount);
    v_refund := v_refund + 1;
  end loop;

  return jsonb_build_object('auto_accepted', 0, 'auto_closed', v_closed,
                            'sent_to_review', v_overdue, 'auto_refund', v_refund);
end;
$$;
revoke all on function public.return_requests_auto() from public, anon, authenticated;

commit;

notify pgrst, 'reload schema';


-- ---------------------------------------------------------------------
-- new-user-vouchers.sql
-- ---------------------------------------------------------------------
-- =====================================================================
-- "New customers only" vouchers. Safe to re-run.
--   * vouchers.new_user_only: can be claimed only by someone who has not
--     paid for an order yet. Once claimed it keeps working until it is
--     used up (per_user_limit) or expires — e.g. 3 free-shipping vouchers.
--   * New accounts get every active new-customer voucher in their wallet
--     automatically when they sign up.
-- The existing claim / checkout functions are not changed: the rule is
-- checked when a voucher is added to someone's wallet.
-- =====================================================================

begin;

alter table public.vouchers add column if not exists new_user_only boolean not null default false;

-- Has this person paid for an order before?
create or replace function public.mivo_has_paid_order(p_user uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.orders
     where user_id = p_user
       and status::text in ('paid','processing','packed','shipped','delivered','completed','refunded','partially_refunded'));
$$;
revoke all on function public.mivo_has_paid_order(uuid) from public, anon, authenticated;

-- New-customer vouchers only go into the wallets of people who haven't bought yet.
create or replace function public.mivo_guard_new_user_voucher()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if exists (select 1 from public.vouchers v where v.id = new.voucher_id and v.new_user_only)
     and public.mivo_has_paid_order(new.user_id) then
    raise exception 'This voucher is for new customers only';
  end if;
  return new;
end;
$$;
drop trigger if exists customer_vouchers_new_user_guard on public.customer_vouchers;
create trigger customer_vouchers_new_user_guard
  before insert on public.customer_vouchers
  for each row execute function public.mivo_guard_new_user_voucher();

-- New sign-ups get the new-customer vouchers straight away.
create or replace function public.mivo_give_new_user_vouchers()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  begin
    insert into public.customer_vouchers (user_id, voucher_id)
    select new.id, v.id
      from public.vouchers v
     where v.new_user_only and v.is_active and now() <= v.ends_at
    on conflict do nothing;
  exception when others then
    null; -- a voucher problem must never block a sign-up
  end;
  return new;
end;
$$;
revoke all on function public.mivo_give_new_user_vouchers() from public, anon, authenticated;
drop trigger if exists mivo_new_user_vouchers on auth.users;
create trigger mivo_new_user_vouchers
  after insert on auth.users
  for each row execute function public.mivo_give_new_user_vouchers();

commit;

notify pgrst, 'reload schema';

